  `name` varchar(255) DEFAULT NULL,
  `nombres` varchar(255) NOT NULL DEFAULT '',
  `apellidos` varchar(255) NOT NULL DEFAULT '',
  `email` varchar(255) DEFAULT NULL,
  `profile_photo_path` varchar(2048) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `role` enum('psicologo','paciente','admin') NOT NULL DEFAULT 'psicologo',
  `profile_completed` tinyint(1) NOT NULL DEFAULT '0',
  `must_change_password` tinyint(1) NOT NULL DEFAULT '0',
  `status` tinyint NOT NULL DEFAULT '1',
  `aprobado` tinyint NOT NULL DEFAULT '1',
  `infracciones_reset_at` timestamp NULL DEFAULT NULL,
  `pregunta_seguridad_1` varchar(255) DEFAULT NULL,
  `respuesta_seguridad_1` varchar(255) DEFAULT NULL,
  `pregunta_seguridad_2` varchar(255) DEFAULT NULL,
  `respuesta_seguridad_2` varchar(255) DEFAULT NULL,
  `pregunta_seguridad_3` varchar(255) DEFAULT NULL,
  `respuesta_seguridad_3` varchar(255) DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `prioridad_siguiente_cita` varchar(255) DEFAULT NULL,
  `cedula` varchar(255) NOT NULL DEFAULT '',
  `genero` varchar(255) NOT NULL DEFAULT '',
  `fecha_nacimiento` date DEFAULT NULL,
  `telefono` varchar(255) NOT NULL DEFAULT '',
  `ubicacion` varchar(255) NOT NULL DEFAULT '',
  `discapacidad` varchar(255) NOT NULL DEFAULT '',
  `tipo_discapacidad` varchar(255) DEFAULT NULL,
  `tiene_hijos` varchar(255) NOT NULL DEFAULT '',
  `numero_hijos` tinyint unsigned DEFAULT NULL,
  `estado_civil` varchar(255) NOT NULL DEFAULT '',
  `perfil_academico` varchar(255) DEFAULT NULL,
  `pnf` varchar(255) DEFAULT NULL,
  `semestre` int DEFAULT NULL,
  `horario_path` varchar(255) DEFAULT NULL,
  `ultima_actividad_chat` timestamp NULL DEFAULT NULL,
  `chat_activo_user_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_cedula_unique` (`cedula`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
